public sealed class ResolvedTypedContextDocument : IEquatable<ResolvedTypedContextDocument>
{
    public ResolvedTypedContextDocument(string kind, string name, int version, string contentSha256) => (Kind, Name, Version, ContentSha256) = (kind, name, version, contentSha256);
    public string Kind { get; } public string Name { get; } public int Version { get; } public string ContentSha256 { get; }
    public bool Equals(ResolvedTypedContextDocument? other) => other is not null && Version == other.Version && Same(Kind, other.Kind) && Same(Name, other.Name) && Same(ContentSha256, other.ContentSha256);
    public override bool Equals(object? obj) => Equals(obj as ResolvedTypedContextDocument);
    public override int GetHashCode() => HashCode.Combine(OrdinalHash(Kind), OrdinalHash(Name), Version, OrdinalHash(ContentSha256));
    private static bool Same(string? x, string? y) => string.Equals(x, y, StringComparison.Ordinal); private static int OrdinalHash(string? value) => StringComparer.Ordinal.GetHashCode(value ?? string.Empty);
}

public sealed class ResolvedTypedContextManifest : IEquatable<ResolvedTypedContextManifest>
{
    private readonly ImmutableArray<ResolvedTypedContextDocument> _documents;
    public ResolvedTypedContextManifest(string seasonPartition, string communityContext, BundesligaSeasonSubcompetition bundesligaSeasonSubcompetition, string profileId, string routingSeedSha256, DateTimeOffset rulesObservedAt, string rulesSchemaVersion, string canonicalRulesSha256, IEnumerable<ResolvedTypedContextDocument> documents)
    { (SeasonPartition, CommunityContext, BundesligaSeasonSubcompetition, ProfileId, RoutingSeedSha256, RulesObservedAt, RulesSchemaVersion, CanonicalRulesSha256) = (seasonPartition, communityContext, bundesligaSeasonSubcompetition, profileId, routingSeedSha256, rulesObservedAt, rulesSchemaVersion, canonicalRulesSha256); _documents = documents?.ToImmutableArray() ?? throw new ArgumentNullException(nameof(documents)); }
    public string SeasonPartition { get; } public string CommunityContext { get; } public BundesligaSeasonSubcompetition BundesligaSeasonSubcompetition { get; } public string ProfileId { get; } public string RoutingSeedSha256 { get; } public DateTimeOffset RulesObservedAt { get; } public string RulesSchemaVersion { get; } public string CanonicalRulesSha256 { get; } public IReadOnlyList<ResolvedTypedContextDocument> Documents => _documents;
    public static ResolvedTypedContextManifest DeserializeCanonical(ReadOnlySpan<byte> bytes) => TypedContextCanonicalJson.DeserializeManifest(bytes);
    public byte[] SerializeCanonical() => TypedContextCanonicalJson.SerializeManifest(this);
    public bool Equals(ResolvedTypedContextManifest? o) => o is not null && RulesObservedAt == o.RulesObservedAt && BundesligaSeasonSubcompetition == o.BundesligaSeasonSubcompetition && Same(SeasonPartition, o.SeasonPartition) && Same(CommunityContext, o.CommunityContext) && Same(ProfileId, o.ProfileId) && Same(RoutingSeedSha256, o.RoutingSeedSha256) && Same(RulesSchemaVersion, o.RulesSchemaVersion) && Same(CanonicalRulesSha256, o.CanonicalRulesSha256) && _documents.SequenceEqual(o._documents);
    public override bool Equals(object? obj) => Equals(obj as ResolvedTypedContextManifest);
    public override int GetHashCode() { var h = new HashCode(); h.Add(SeasonPartition, StringComparer.Ordinal); h.Add(CommunityContext, StringComparer.Ordinal); h.Add(BundesligaSeasonSubcompetition); h.Add(ProfileId, StringComparer.Ordinal); h.Add(RoutingSeedSha256, StringComparer.Ordinal); h.Add(RulesObservedAt); h.Add(RulesSchemaVersion, StringComparer.Ordinal); h.Add(CanonicalRulesSha256, StringComparer.Ordinal); foreach (var d in _documents) h.Add(d); return h.ToHashCode(); }
    private static bool Same(string? x, string? y) => string.Equals(x, y, StringComparison.Ordinal);
}

